import java.util.*;

class Solution {
  public long countSubarrays(int[] nums, int k) {
    Map<Integer, Long> previous = new HashMap<>();
    long answer = 0;
    for (int value : nums) {
      Map<Integer, Long> current = new HashMap<>();
      current.merge(value, 1L, Long::sum);
      for (Map.Entry<Integer, Long> e : previous.entrySet())
        current.merge(e.getKey() & value, e.getValue(), Long::sum);
      answer += current.getOrDefault(k, 0L);
      previous = current;
    }
    return answer;
  }
}
